package io.github.ningpp.compat;

/**
 * Replacement for System.Buffers.Text.Utf8Parser (generated by CSharpToJava converter).
 * Parses UTF-8 byte spans (Integer[] holding byte values).
 */
public final class Utf8Parser {
    private Utf8Parser() {
    }

    private static String spanToString(ReadOnlySpan<Integer> source) {
        StringBuilder sb = new StringBuilder(source.length());
        for (int i = 0; i < source.length(); i++) {
            sb.append((char) (source.get(i) & 0xFF));
        }
        return sb.toString();
    }

    private static boolean parseInteger(String text, int radix, int bits, IntHolder value, IntHolder bytesConsumed) {
        if (text.isEmpty()) {
            return false;
        }
        try {
            long parsed = Long.parseLong(text.trim(), radix);
            if (bits < 64) {
                long min = -(1L << (bits - 1));
                long max = (1L << (bits - 1)) - 1;
                if (parsed < min || parsed > max) {
                    return false;
                }
            }
            value.value = (int) parsed;
            bytesConsumed.value = text.length();
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out int, out int). */
    public static boolean tryParse(ReadOnlySpan<Integer> source, IntHolder value, IntHolder bytesConsumed) {
        return parseInteger(spanToString(source), 10, 32, value, bytesConsumed);
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out int, out int, char standardFormat). */
    public static boolean tryParse(ReadOnlySpan<Integer> source, IntHolder value, IntHolder bytesConsumed, char standardFormat) {
        int radix = (standardFormat == 'x' || standardFormat == 'X') ? 16 : 10;
        return parseInteger(spanToString(source), radix, 32, value, bytesConsumed);
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out uint, out int). */
    public static boolean tryParseUInt32(ReadOnlySpan<Integer> source, IntHolder value, IntHolder bytesConsumed) {
        return parseInteger(spanToString(source), 10, 32, value, bytesConsumed);
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out long, out int). */
    public static boolean tryParseInt64(ReadOnlySpan<Integer> source, LongHolder value, IntHolder bytesConsumed) {
        String text = spanToString(source).trim();
        if (text.isEmpty()) return false;
        try {
            value.value = Long.parseLong(text);
            bytesConsumed.value = text.length();
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out ulong, out int). */
    public static boolean tryParseUInt64(ReadOnlySpan<Integer> source, LongHolder value, IntHolder bytesConsumed) {
        String text = spanToString(source).trim();
        if (text.isEmpty()) return false;
        try {
            value.value = Long.parseUnsignedLong(text);
            bytesConsumed.value = text.length();
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out double, out int). */
    public static boolean tryParseDouble(ReadOnlySpan<Integer> source, DoubleHolder value, IntHolder bytesConsumed) {
        String text = spanToString(source).trim();
        if (text.isEmpty()) return false;
        try {
            value.value = Double.parseDouble(text);
            bytesConsumed.value = text.length();
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out float, out int). */
    public static boolean tryParseSingle(ReadOnlySpan<Integer> source, FloatHolder value, IntHolder bytesConsumed) {
        String text = spanToString(source).trim();
        if (text.isEmpty()) return false;
        try {
            value.value = Float.parseFloat(text);
            bytesConsumed.value = text.length();
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out float, out int, char standardFormat). */
    public static boolean tryParse(ReadOnlySpan<Integer> source, FloatHolder value, IntHolder bytesConsumed, char standardFormat) {
        return tryParseSingle(source, value, bytesConsumed);
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out double, out int, char standardFormat). */
    public static boolean tryParse(ReadOnlySpan<Integer> source, DoubleHolder value, IntHolder bytesConsumed, char standardFormat) {
        return tryParseDouble(source, value, bytesConsumed);
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out byte, out int). */
    public static boolean tryParse(ReadOnlySpan<Integer> source, ByteHolder value, IntHolder bytesConsumed) {
        String text = spanToString(source).trim();
        if (text.isEmpty()) return false;
        try {
            value.value = Byte.parseByte(text);
            bytesConsumed.value = text.length();
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out short, out int). */
    public static boolean tryParse(ReadOnlySpan<Integer> source, ShortHolder value, IntHolder bytesConsumed) {
        String text = spanToString(source).trim();
        if (text.isEmpty()) return false;
        try {
            value.value = Short.parseShort(text);
            bytesConsumed.value = text.length();
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out long, out int). */
    public static boolean tryParse(ReadOnlySpan<Integer> source, LongHolder value, IntHolder bytesConsumed) {
        return tryParseInt64(source, value, bytesConsumed);
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out UUID, out int, char standardFormat). */
    public static boolean tryParseUuid(ReadOnlySpan<Integer> source, ObjectHolder<UUID> value, IntHolder bytesConsumed, char standardFormat) {
        String text = spanToString(source).trim();
        if (text.isEmpty()) return false;
        try {
            value.value = UUID.fromString(text);
            bytesConsumed.value = text.length();
            return true;
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out DateTimeOffset, out int, char standardFormat). */
    public static boolean tryParseDateTimeOffset(ReadOnlySpan<Integer> source, ObjectHolder<CSharpDateTimeOffset> value, IntHolder bytesConsumed, char standardFormat) {
        String text = spanToString(source).trim();
        if (text.isEmpty()) return false;
        try {
            value.value = CSharpDateTimeOffset.parse(text);
            bytesConsumed.value = text.length();
            return true;
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out DateTime, out int, char standardFormat). */
    public static boolean tryParseDateTime(ReadOnlySpan<Integer> source, ObjectHolder<CSharpDateTime> value, IntHolder bytesConsumed, char standardFormat) {
        String text = spanToString(source).trim();
        if (text.isEmpty()) return false;
        try {
            value.value = CSharpDateTime.parse(text);
            bytesConsumed.value = text.length();
            return true;
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

    /** Mirrors Utf8Parser.TryParse(ReadOnlySpan&lt;byte&gt;, out Decimal, out int, char standardFormat). */
    public static boolean tryParseDecimal(ReadOnlySpan<Integer> source, ObjectHolder<Decimal> value, IntHolder bytesConsumed, char standardFormat) {
        String text = spanToString(source).trim();
        if (text.isEmpty()) return false;
        try {
            value.value = Decimal.parse(text);
            bytesConsumed.value = text.length();
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }
}
